function goFetch(url, fetchOptions, options) {
    return fetch(url, fetchOptions)
        .then((response) => {
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.json().catch(() => {
            throw new Error("Failed to parse JSON");
        });
    })
        .then((data) => {
        const result = options?.responseTransformer
            ? [options.responseTransformer(data), null]
            : [data, null];
        return result;
    })
        .catch((e) => {
        const error = options?.errorTransformer
            ? options.errorTransformer(e)
            : (e instanceof Error ? e.message : "Failed to fetch data");
        const result = [null, error];
        return result;
    });
}

